"""TG 绿点展示计划：上下班窗口内随机时刻，仅控在线状态，不触发真实打卡。"""
from __future__ import annotations

import asyncio
import json
import logging
import os
import secrets
import threading
from datetime import date, datetime, timedelta
from zoneinfo import ZoneInfo

from config import (
    TG_PRESENCE_CHECKIN_WINDOW_END,
    TG_PRESENCE_CHECKIN_WINDOW_START,
    TG_PRESENCE_CHECKOUT_SATURDAY_WINDOW_END,
    TG_PRESENCE_CHECKOUT_SATURDAY_WINDOW_START,
    TG_PRESENCE_CHECKOUT_WINDOW_END,
    TG_PRESENCE_CHECKOUT_WINDOW_START,
    TG_PRESENCE_PLAN_STATE_PATH,
    TG_WORK_ONLINE_REST_WINDOWS,
    TG_WORK_ONLINE_REST_WINDOWS_SATURDAY,
)
from cn_punch_calendar import should_skip_punch
from work_hours import in_rest_window, rest_windows_for_weekday

log = logging.getLogger(__name__)
_BJ = ZoneInfo('Asia/Shanghai')
_PLAN_KEY_PREFIX = '_plan_'
_KEEP_PLAN_DAYS = 3
_LEGACY_STATE_PATH = os.path.join(
    os.path.dirname(TG_PRESENCE_PLAN_STATE_PATH), 'jike_checkin_state.json',
)
_STATE_LOCK = threading.Lock()


def _parse_hhmm(s: str) -> tuple[int, int] | None:
    parts = (s or '').strip().split(':')
    if len(parts) != 2:
        return None
    try:
        h, m = int(parts[0]), int(parts[1])
        if h == 24 and m == 0:
            return 24, 0
        if 0 <= h <= 23 and 0 <= m <= 59:
            return h, m
    except ValueError:
        pass
    return None


def _window_bounds(start_hhmm: str, end_hhmm: str, day: date) -> tuple[datetime, datetime] | None:
    start_parts = _parse_hhmm(start_hhmm)
    end_parts = _parse_hhmm(end_hhmm)
    if not start_parts or not end_parts:
        return None
    sh, sm = start_parts
    eh, em = end_parts
    start = datetime(day.year, day.month, day.day, sh, sm, tzinfo=_BJ)
    if eh == 24 and em == 0:
        end = datetime(day.year, day.month, day.day, tzinfo=_BJ) + timedelta(days=1)
    else:
        end = datetime(day.year, day.month, day.day, eh, em, tzinfo=_BJ)
    if end <= start:
        return None
    return start, end


def _random_in_window(start: datetime, end: datetime) -> datetime:
    span = int((end - start).total_seconds())
    if span <= 0:
        return start
    offset = secrets.randbelow(span + 1)
    return start + timedelta(seconds=offset)


def _plan_key(kind: str, day: date) -> str:
    return f'{kind}{_PLAN_KEY_PREFIX}{day.isoformat()}'


def _load_state_raw() -> dict:
    path = TG_PRESENCE_PLAN_STATE_PATH
    if not os.path.isfile(path) and os.path.isfile(_LEGACY_STATE_PATH):
        try:
            with open(_LEGACY_STATE_PATH, encoding='utf-8') as f:
                legacy = json.load(f)
            if isinstance(legacy, dict):
                plans = {
                    k: v for k, v in legacy.items()
                    if _PLAN_KEY_PREFIX in k and isinstance(v, str)
                }
                if plans:
                    os.makedirs(os.path.dirname(path), exist_ok=True)
                    with open(path, 'w', encoding='utf-8') as out:
                        json.dump(plans, out, ensure_ascii=False, indent=2)
                    log.info('[presence-plan] migrated %d plan keys from legacy state', len(plans))
        except (OSError, json.JSONDecodeError) as exc:
            log.warning('[presence-plan] legacy migrate skip: %s', exc)
    if not os.path.isfile(path):
        return {}
    try:
        with open(path, encoding='utf-8') as f:
            data = json.load(f)
        return data if isinstance(data, dict) else {}
    except (OSError, json.JSONDecodeError):
        return {}


def _save_state(state: dict) -> None:
    os.makedirs(os.path.dirname(TG_PRESENCE_PLAN_STATE_PATH), exist_ok=True)
    tmp = TG_PRESENCE_PLAN_STATE_PATH + '.tmp'
    with open(tmp, 'w', encoding='utf-8') as f:
        json.dump(state, f, ensure_ascii=False, indent=2)
    os.replace(tmp, TG_PRESENCE_PLAN_STATE_PATH)


def load_state() -> dict:
    with _STATE_LOCK:
        return dict(_load_state_raw())


def save_state(state: dict) -> None:
    with _STATE_LOCK:
        _save_state(state)


def _purge_stale_plans(state: dict, today: date) -> bool:
    changed = False
    cutoff = today - timedelta(days=_KEEP_PLAN_DAYS)
    for key in list(state.keys()):
        if _PLAN_KEY_PREFIX not in key:
            continue
        day_str = key.rsplit(_PLAN_KEY_PREFIX, 1)[-1]
        try:
            plan_day = date.fromisoformat(day_str)
        except ValueError:
            continue
        if plan_day < cutoff:
            del state[key]
            changed = True
    return changed


def _window_for(kind: str, day: date) -> tuple[str, str]:
    if kind == 'checkin':
        return TG_PRESENCE_CHECKIN_WINDOW_START, TG_PRESENCE_CHECKIN_WINDOW_END
    if day.weekday() == 5:
        return (
            TG_PRESENCE_CHECKOUT_SATURDAY_WINDOW_START,
            TG_PRESENCE_CHECKOUT_SATURDAY_WINDOW_END,
        )
    return TG_PRESENCE_CHECKOUT_WINDOW_START, TG_PRESENCE_CHECKOUT_WINDOW_END


def _windows(day: date) -> tuple[tuple[str, str, str], ...]:
    cin_s, cin_e = _window_for('checkin', day)
    cout_s, cout_e = _window_for('checkout', day)
    return (
        ('checkin', cin_s, cin_e),
        ('checkout', cout_s, cout_e),
    )


def ensure_daily_plans(day: date, *, force_new: bool = False) -> dict[str, datetime]:
    skip, reason = should_skip_punch(day)
    if skip:
        log.info('[presence-plan] skip plan day=%s reason=%s', day.isoformat(), reason)
        return {}

    state = load_state()
    changed = _purge_stale_plans(state, day)
    planned: dict[str, datetime] = {}

    for kind, ws, we in _windows(day):
        key = _plan_key(kind, day)
        bounds = _window_bounds(ws, we, day)
        if not bounds:
            continue
        start, end = bounds

        if not force_new and key in state:
            try:
                saved = datetime.fromisoformat(state[key])
                if saved.tzinfo is None:
                    saved = saved.replace(tzinfo=_BJ)
                if start <= saved < end:
                    planned[kind] = saved
                    continue
            except ValueError:
                pass

        when = _random_in_window(start, end)
        state[key] = when.isoformat()
        planned[kind] = when
        changed = True

    if changed:
        save_state(state)
    return planned


def _aware(dt: datetime) -> datetime:
    if dt.tzinfo is None:
        return dt.replace(tzinfo=_BJ)
    return dt.astimezone(_BJ)


def punch_aligned_bounds(now: datetime | None = None) -> tuple[datetime, datetime] | None:
    """当天随机上下班计划构成的绿点窗 [checkin_plan, checkout_plan)。"""
    now = _aware(now or datetime.now(_BJ))
    today = now.date()
    skip, _ = should_skip_punch(today)
    if skip:
        return None
    plans = ensure_daily_plans(today)
    start = plans.get('checkin')
    end = plans.get('checkout')
    if not start or not end:
        return None
    start, end = _aware(start), _aware(end)
    if end <= start:
        return None
    return start, end


def should_appear_online(now: datetime | None = None) -> bool:
    """别人看到的绿点是否该亮：在当天随机上下班计划窗内，且不在休息窗。"""
    now = _aware(now or datetime.now(_BJ))
    skip, _ = should_skip_punch(now.date())
    if skip:
        return False
    resting, _ = in_rest_window(
        now,
        windows=rest_windows_for_weekday(
            now.weekday(),
            weekday_raw=TG_WORK_ONLINE_REST_WINDOWS,
            saturday_raw=TG_WORK_ONLINE_REST_WINDOWS_SATURDAY,
        ),
    )
    if resting:
        return False
    bounds = punch_aligned_bounds(now)
    if not bounds:
        return False
    start, end = bounds
    return start <= now < end


async def _plan_refresh_loop() -> None:
    log.info(
        '[presence-plan] started checkin=%s~%s checkout=%s~%s sat_checkout=%s~%s',
        TG_PRESENCE_CHECKIN_WINDOW_START,
        TG_PRESENCE_CHECKIN_WINDOW_END,
        TG_PRESENCE_CHECKOUT_WINDOW_START,
        TG_PRESENCE_CHECKOUT_WINDOW_END,
        TG_PRESENCE_CHECKOUT_SATURDAY_WINDOW_START,
        TG_PRESENCE_CHECKOUT_SATURDAY_WINDOW_END,
    )
    last_plan_day: date | None = None
    while True:
        try:
            now = datetime.now(_BJ)
            today = now.date()
            if last_plan_day != today:
                plans = ensure_daily_plans(today)
                if plans:
                    parts = [f'{k}={v.strftime("%H:%M:%S")}' for k, v in sorted(plans.items())]
                    log.info('[presence-plan] today %s', ', '.join(parts))
                else:
                    skip, reason = should_skip_punch(today)
                    if skip:
                        log.info('[presence-plan] today off reason=%s', reason)
                last_plan_day = today
            await asyncio.sleep(3600)
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            log.exception('[presence-plan] loop error: %s', exc)
            await asyncio.sleep(60)


async def start_presence_plan_scheduler() -> None:
    asyncio.create_task(_plan_refresh_loop())
